USE CATALOG dcp_synth; CREATE OR REPLACE VIEW `04_presentation`.vw_consent_current_summary AS SELECT consent_scope,purpose,recipient,current_state,COUNT(*) patient_scope_count,MAX(effective_at) latest_effective_at FROM `03_gold`.dp10_patient_consent_current GROUP BY consent_scope,purpose,recipient,current_state; CREATE OR REPLACE VIEW `04_presentation`.vw_consent_propagation_summary AS SELECT target_system,target_status,COUNT(*) propagation_count,MAX(ingested_at) refreshed_at FROM `03_gold`.dp11_consent_propagation_status GROUP BY target_system,target_status; CREATE OR REPLACE VIEW `04_presentation`.vw_compliance_control_summary AS SELECT domain,result,approval_status,COUNT(*) control_count,MAX(assessed_at) latest_assessed_at FROM `03_gold`.dp15_healthcare_compliance_monitoring GROUP BY domain,result,approval_status;